def is_power_of_5(num):
    if num <= 0:
        return False
    if num == 1:
        return True
    while num % 5 == 0:
        num //= 5
    return num == 1

results = {}
for n in range(3, 11):
    value = (2**n) - 3
    is_power = is_power_of_5(value)
    if is_power:
        # Find k such that 5^k = value
        k = 0
        temp = value
        while temp > 1:
            temp //= 5
            k += 1
        results[n] = k

print("Results (n, k) where 2^n - 3 = 5^k:")
for n, k in results.items():
    print(f"n={n}, k={k}")

if not results:
    print("No solutions found in the range.")

def is_power_of_5(m):
    if m <= 0:
        return False
    while m > 1:
        if m % 5 != 0:
            return False
        m //= 5
    return True

print("Checking for n >= 3 up to n=15:")
for n in range(3, 16):
    m = (2**n) - 3
    if is_power_of_5(m):
        print(f"n={n} works: 2^{n} - 3 = {m}")
